pattern ${name}(${param}) {
  match<${param}:${duration}> {
    on event {
      ${alias} | count >= ${threshold};
    }
  } -> score(${score})
}

rule ${name} {
  meta {
    lang = "2.1"
    contract_version = "1"
    description = "${description}"
  }
  events {
    ${alias}: ${window}
  }
  match<${key}:${duration}> {
    on event {
      ${alias} | count >= ${threshold};
    }
  } -> score(${score})
  entity(${entity_type}, ${alias}.${id_field})
  yield ${target}@v1 (
    ${field} = ${value}
  )
}

test ${name} for ${rule} {
  input {
    row(${alias}, ${field} = ${value});
  }
  expect {
    hits == ${count};
  }
}
